import{c as t,Q as n,j as e,m as l}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"SetBatchInfoForNormal","description":"","frontmatter":{},"headers":[{"level":1,"title":"SetBatchInfoForNormal","slug":"setbatchinfofornormal"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Tiling侧接口/Matmul-Tiling类/SetBatchInfoForNormal.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Tiling侧接口/Matmul-Tiling类/SetBatchInfoForNormal.md"}'),s={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Tiling侧接口/Matmul-Tiling类/SetBatchInfoForNormal.md"};function i(p,a,r,o,c,h){return n(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="setbatchinfofornormal" tabindex="-1">SetBatchInfoForNormal <a class="header-anchor" href="#setbatchinfofornormal" aria-label="Permalink to &quot;SetBatchInfoForNormal&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>设置A/B矩阵的M/N/K轴信息，以及A/B矩阵的Batch数。Layout类型为NORMAL的场景，调用<a href="./../../Matmul-Kernel侧接口/IterateBatch.html">IterateBatch</a>或者<a href="./../../Matmul-Kernel侧接口/IterateNBatch.html">IterateNBatch</a>接口之前，需要在Host侧Tiling实现中通过本接口设置A/B矩阵的M/N/K轴等信息。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int32_t SetBatchInfoForNormal(int32_t batchA, int32_t batchB, int32_t m, int32_t n, int32_t k)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>batchA</td><td>输入</td><td>A矩阵的batch数</td></tr><tr><td>batchB</td><td>输入</td><td>B矩阵的batch数</td></tr><tr><td>m</td><td>输入</td><td>A矩阵的M轴信息</td></tr><tr><td>n</td><td>输入</td><td>B矩阵的N轴信息</td></tr><tr><td>k</td><td>输入</td><td>A/B矩阵的K轴信息</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>-1表示设置失败； 0表示设置成功。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>Layout类型为NORMAL的场景，调用<a href="./../../Matmul-Kernel侧接口/IterateBatch.html">IterateBatch</a>或者<a href="./../../Matmul-Kernel侧接口/IterateNBatch.html">IterateNBatch</a>接口之前，需要在Host侧Tiling实现中通过本接口设置A/B矩阵的M/N/K轴等信息。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());</span></span>
<span class="line"><span>matmul_tiling::MultiCoreMatmulTiling tiling(ascendcPlatform);   </span></span>
<span class="line"><span>int32_t M = 32;</span></span>
<span class="line"><span>int32_t N = 256;</span></span>
<span class="line"><span>int32_t K = 64;</span></span>
<span class="line"><span>tiling.SetDim(1);</span></span>
<span class="line"><span>tiling.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);</span></span>
<span class="line"><span>tiling.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);</span></span>
<span class="line"><span>tiling.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);</span></span>
<span class="line"><span>tiling.SetBiasType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);</span></span>
<span class="line"><span>tiling.SetShape(M, N, K);</span></span>
<span class="line"><span>tiling.SetOrgShape(M, N, K);</span></span>
<span class="line"><span>tiling.SetBias(true);</span></span>
<span class="line"><span>tiling.SetBufferSpace(-1, -1, -1);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>constexpr int32_t BATCH_NUM = 3;</span></span>
<span class="line"><span>tiling.SetBatchInfoForNormal(BATCH_NUM, BATCH_NUM, M, N, K);  // 设置矩阵排布</span></span>
<span class="line"><span>tiling.SetBufferSpace(-1, -1, -1);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>optiling::TCubeTiling tilingData;</span></span>
<span class="line"><span>int ret = tiling.GetTiling(tilingData);</span></span></code></pre></div>`,14)])])}const u=t(s,[["render",i]]);export{m as __pageData,u as default};
